    "ru": "Годы строительства, содержание, демография и нагрузка аппарата идут своим чередом. Поздний запуск оставляет меньше лет полезной работы. У двух предложений софинансирования есть заранее объявленный срок. Просмотр вопросов ничего не списывает и не перебрасывает случайность.",
