    "en": "The model shows your programmes, not literal geography or facility counts. Use zoom buttons; on desktop drag to pan a close view.",
    "zh": "模型展示您的项目，并非精确地理或机构数量。请用按钮缩放；在电脑上，可拖动放大后的地图。"
