    "ru": "Принято решений: {0}/20. Ниже — текущий расчёт; окончательная оценка сохранится при завершении.",
    "en": "Decisions made: {0}/20. This is the current calculation; the final grade is saved when the campaign ends.",
    "zh": "已作决策：{0}/20。下方为当前计算结果；最终成绩将在结束时保存。"
