    "en": "{0} Before adjustments: {1}; c = {2}; after progress adjustment: {3}. Handover cap multiplier: {4}. Rounded contribution: {5} / 1.",
    "zh": "{0}调整前：{1}；c = {2}；考虑完成比例后：{3}。移交管理权的限制系数：{4}。舍入后的贡献：{5} / 1。"
